+          displayName += ` <${address}>`;
+          localPart = address = "";
+          afterAddress = false;
+        }
         if (inAngle) {
           // Interpret the address we were parsing as a name.
-          if (address.length > 0) {
+          if (address) {
             displayName = address;
           }
           localPart = address = "";
